let map;
let markersList = [];
let activeInfoWindow = null;
function initMap() {
  const defaultCenter = {
    lat: 28.57,
    lng: 77.23
  };
  map = new google.maps.Map(document.getElementById("map"), {
    zoom: 12,
    center: defaultCenter
  });
  appsmith.onReady(() => {
    appsmith.onModelChange(model => {
      // 1. Render all pins on initial load or list update
      if (model && Array.isArray(model.markers)) {
        renderMarkers(model.markers);
      }

      // 2. Center map and open InfoWindow Title on Table Row Select
      if (model && model.selectedMarker && model.selectedMarker.lat != null && model.selectedMarker.long != null) {
        const selLat = parseFloat(model.selectedMarker.lat);
        const selLng = parseFloat(model.selectedMarker.long);
        if (!isNaN(selLat) && !isNaN(selLng)) {
          const newPos = {
            lat: selLat,
            lng: selLng
          };

          // Pan and zoom map to selected location
          map.panTo(newPos);
          map.setZoom(16);

          // Find matching marker on map
          const matchedMarker = markersList.find(m => {
            const pos = m.getPosition();
            return Math.abs(pos.lat() - selLat) < 0.0001 && Math.abs(pos.lng() - selLng) < 0.0001;
          });

          // Open title popup over the marker
          if (matchedMarker) {
            if (activeInfoWindow) {
              activeInfoWindow.close();
            }
            matchedMarker.infoWindow.open(map, matchedMarker);
            activeInfoWindow = matchedMarker.infoWindow;
          }
        }
      }
    });
  });
}
function renderMarkers(data) {
  // Clear existing pins and popups
  markersList.forEach(m => m.setMap(null));
  markersList = [];
  if (!data || !data.length) return;
  const bounds = new google.maps.LatLngBounds();
  data.forEach(item => {
    const lat = parseFloat(item.lat);
    const lng = parseFloat(item.long);
    if (isNaN(lat) || isNaN(lng)) return;
    const pos = {
      lat,
      lng
    };
    const marker = new google.maps.Marker({
      position: pos,
      map: map,
      title: item.title || ''
    });

    // Create InfoWindow with Title
    const infoWindow = new google.maps.InfoWindow({
      content: `<div style="padding:4px; font-weight:bold; font-family:sans-serif;">${item.title || 'Location'}</div>`
    });

    // Attach infoWindow to marker object
    marker.infoWindow = infoWindow;
    marker.addListener("click", () => {
      if (activeInfoWindow) {
        activeInfoWindow.close();
      }
      infoWindow.open(map, marker);
      activeInfoWindow = infoWindow;
    });
    markersList.push(marker);
    bounds.extend(pos);
  });
}

// Initial script execution
if (window.google && window.google.maps) {
  initMap();
}

